function risky() {
  throw new Error('kaboom');
}
try {
  console.log('before');
  risky();
  console.log('after');
} catch (err) {
  console.log('caught: ' + err.message);
} finally {
  console.log('cleanup');
}
console.log('done');

function parsePositive(s) {
  const n = Number(s);
  if (Number.isNaN(n)) throw new Error('not a number');
  if (n <= 0) throw new Error('not positive');
  return n;
}
for (const input of ['5', 'abc', '-2']) {
  try {
    console.log('ok: ' + parsePositive(input));
  } catch (err) {
    console.log('err: ' + err.message);
  }
}

function attempt(shouldThrow) {
  try {
    if (shouldThrow) throw new Error('nope');
    console.log('try ran');
    return 'from try';
  } catch (err) {
    console.log('catch ran');
    return 'from catch';
  } finally {
    console.log('finally ran');
  }
}
console.log(attempt(false));
console.log(attempt(true));

