export class NotFoundError extends Error {
  constructor(id) {
    super(`todo ${id} not found`);
    this.name = 'NotFoundError';
    this.code = 'NOT_FOUND';
  }
}

export class ValidationError extends Error {
  constructor(reason) {
    super(reason);
    this.name = 'ValidationError';
    this.code = 'VALIDATION';
  }
}

export function getTodo(todos, id) {
  const todo = todos.find((t) => t.id === id);
  if (!todo) throw new NotFoundError(id);
  return todo;
}

export function createTodo(todos, title) {
  if (typeof title !== 'string' || title.trim() === '') {
    throw new ValidationError('title required');
  }
  return [...todos, { id: todos.length + 1, title: title.trim(), done: false }];
}

export function handle(fn) {
  try {
    return { status: 200, body: fn() };
  } catch (err) {
    let status = 500;
    if (err instanceof NotFoundError) status = 404;
    else if (err instanceof ValidationError) status = 400;
    return { status, body: { error: err.message, code: err.code ?? 'INTERNAL' } };
  }
}

