}

bootforge/errors-modules/modules-and-dat.solution:
export function makeBank(openingCents) {
  let balanceCents = openingCents;
  const assertAmount = (cents) => {
    if (!Number.isInteger(cents) || cents < 1) throw new Error('invalid amount');
  };
  return {
    balance() {
      return balanceCents;
    },
    deposit(cents) {
      assertAmount(cents);
      balanceCents += cents;
      return balanceCents;
    },
    withdraw(cents) {
      assertAmount(cents);
      if (cents > balanceCents) throw new Error('insufficient funds');
      balanceCents -= cents;
      return balanceCents;
    },
  };
}

