bootforge/errors-modules/modules-and-dat.solution:
export function makeTodoStore() {
  const todos = [];
  let nextId = 1;
  return {
    add(title) {
      const todo = { id: nextId, title, done: false };
      nextId += 1;
      todos.push(todo);
      return todo.id;
    },
    complete(id) {
      const todo = todos.find((t) => t.id === id);
      if (!todo) return false;
      todo.done = true;
      return true;
    },
    list() {
      return todos.map((t) => ({ ...t }));
    },
    stats() {
      return {
        total: todos.length,
        done: todos.filter((t) => t.done).length,
      };
    },
  };
}

